// swift-tools-version:5.9
import PackageDescription

// API client for the Third Place backend, generated by hand from openapi.yaml
// (repo root) — every model mirrors a schema in the contract and the test
// fixtures are the contract's own examples. Platform-neutral so it builds and
// tests on macOS too (`swift test`), not only inside the visionOS app.
let package = Package(
    name: "ThirdPlaceAPI",
    platforms: [.visionOS(.v1), .iOS(.v17), .macOS(.v14)],
    products: [
        .library(name: "ThirdPlaceAPI", targets: ["ThirdPlaceAPI"])
    ],
    targets: [
        .target(name: "ThirdPlaceAPI"),
        .testTarget(
            name: "ThirdPlaceAPITests",
            dependencies: ["ThirdPlaceAPI"],
            resources: [.copy("Fixtures")]
        ),
    ],
    swiftLanguageVersions: [.v5]
)
